public static String exePipedCmd(List<String[]> argvSegments, File workDir, long timeoutMs) {
        if (argvSegments == null || argvSegments.isEmpty()) {
            logger.error("exePipedCmd called with empty argvSegments");
            return null;
        }
        if (argvSegments.size() == 1) {
            return exeCmd(Arrays.asList(argvSegments.get(0)), workDir, timeoutMs);
        }
        long timeout = timeoutMs > 0 ? timeoutMs : DEFAULT_TIMEOUT_MS;
        List<Process> processes = new ArrayList<>(argvSegments.size());
        List<Thread> pumpers = new ArrayList<>(argvSegments.size() - 1);
        List<StreamGobbler> stderrGobblers = new ArrayList<>(argvSegments.size());
        StreamGobbler tailStdoutGobbler = null;
        try {
            for (int i = 0; i < argvSegments.size(); i++) {
                String[] argv = argvSegments.get(i);
                if (argv == null || argv.length == 0) {
                    logger.error("exePipedCmd segment[{}] is empty", i);
                    return null;
                }
                ProcessBuilder pb = new ProcessBuilder(argv);
                if (workDir != null) {
                    pb.directory(workDir);
                }
                pb.redirectErrorStream(false);
                Process p = pb.start();
                processes.add(p);
                stderrGobblers.add(new StreamGobbler(p.getErrorStream(), "stderr-piped-" + argv[0]));
                stderrGobblers.get(i).start();
            }
            // Chain adjacent segments: upstream stdout -> downstream stdin.
            for (int i = 0; i < processes.size() - 1; i++) {
                Process upstream = processes.get(i);
                Process downstream = processes.get(i + 1);
                Thread pump = new Thread(new StreamPump(upstream.getInputStream(), downstream.getOutputStream()),
                        "pipe-pump-" + i);
                pump.setDaemon(true);
                pump.start();
                pumpers.add(pump);
            }
            Process tail = processes.get(processes.size() - 1);
            tailStdoutGobbler = new StreamGobbler(tail.getInputStream(), "stdout-piped-tail");
            tailStdoutGobbler.start();

            long deadline = System.currentTimeMillis() + timeout;
            for (Process p : processes) {
                long remain = deadline - System.currentTimeMillis();
                if (remain <= 0) {
                    logger.error("exePipedCmd timeout, argvSegments={}", argvSegmentsToString(argvSegments));
                    return null;
                }
                if (!p.waitFor(remain, TimeUnit.MILLISECONDS)) {
                    logger.error("exePipedCmd timeout at one segment, argvSegments={}",
                            argvSegmentsToString(argvSegments));
                    return null;
                }
            }
            for (Thread pump : pumpers) {
                pump.join(1000);
            }
            tailStdoutGobbler.join(1000);
            for (StreamGobbler g : stderrGobblers) {
                g.join(1000);
            }

            int tailExit = tail.exitValue();
            if (tailExit != 0) {
                logger.error("exePipedCmd tail non-zero exit={} stderr={}", tailExit,
                        truncate(stderrGobblers.get(stderrGobblers.size() - 1).getResult(), STDERR_LOG_MAX_BYTES));
                return null;
            }
            return tailStdoutGobbler.getResult();
        } catch (Exception e) {
            logger.error("exePipedCmd error argvSegments={}", argvSegmentsToString(argvSegments), e);
            return null;
        } finally {
            // Force-kill every child on any error/timeout path so we never leak zombies or fds.
            for (Process p : processes) {
                try {
                    if (p != null && p.isAlive()) {
                        p.destroyForcibly();
                    }
                } catch (Exception ignore) {
                }
                closeQuietly(p);
            }
        }
    }

String validate(String rawCmd) {
        if (StringUtils.isBlank(rawCmd)) {
            return null;
        }

        // metacharacter blacklist (whole string, before splitting).
        // Offending chars are wrapped with [] so callers can unambiguously see the boundary,
        // e.g. "DISALLOWED_META_CHAR: [`]" rather than a bare backtick which is easy to miss.
        String metaHit = firstMetaCharHit(rawCmd);
        if (StringUtils.isNotBlank(metaHit)) {
            if (InlongConstants.ASTERISK.equals(metaHit) || InlongConstants.QUESTION_MARK.equals(metaHit)) {
                return "DISALLOWED_META_CHAR: [" + metaHit + "]"
                        + " — glob wildcards are not supported (Agent runs commands without a shell,"
                        + " so [*] and [?] will NOT be expanded); please specify explicit file paths";
            }
            return "DISALLOWED_META_CHAR: [" + metaHit + "]";
        }
        if (rawCmd.indexOf(InlongConstants.NEW_LINE_CHAR) >= 0
                || rawCmd.indexOf(InlongConstants.CARRIAGE_RETURN_CHAR) >= 0) {
            return "DISALLOWED_META_CHAR: line-break";
        }

        Set<String> whitelist = getEffectiveWhitelist();

        // Split by ';' into sub-commands (quote-aware), then by '|' into pipe segments
        List<String> segments = splitTopLevel(rawCmd, InlongConstants.SEMICOLON_CHAR);
        if (segments == null) {
            return "DISALLOWED_META_CHAR: unterminated quote";
        }
        for (String seg : segments) {
            if (StringUtils.isBlank(seg)) {
                continue;
            }
            List<String> pipeSegs = splitTopLevel(seg, InlongConstants.PIPE_CHAR);
            if (pipeSegs == null) {
                return "DISALLOWED_META_CHAR: unterminated quote in pipe segment";
            }
            for (String pipeSeg : pipeSegs) {
                if (StringUtils.isBlank(pipeSeg)) {
                    continue;
                }
                List<String> argv = tokenize(pipeSeg);
                if (argv.isEmpty()) {
                    continue;
                }
                String cmdName = argv.get(0);

                // argv[0] whitelist
                if (!whitelist.contains(cmdName)) {
                    return cmdName;
                }

                // forbid sh/bash -c flag (inline script execution)
                if (("sh".equals(cmdName) || "bash".equals(cmdName)) && argv.size() > 1) {
                    for (int i = 1; i < argv.size(); i++) {
                        if (argv.get(i).startsWith("-c")) {
                            return "FORBIDDEN_SH_C_FLAG: " + cmdName + " " + argv.get(i);
                        }
                    }
                }
            }
        }
        return null;
    }

public Object parseByColumnParser(SourceData sourceData, int rowIndex, Context context) {
        String path = ((ColumnParser) pathParser).getFieldName();
        if (path == null) {
            return null;
        }
        PbSourceData pbData = (PbSourceData) sourceData;
        if (StringUtils.equals(PbSourceData.ROOT, path)) {
            return pbData.getRoot().toByteArray();
        }
        // node list
        List<PbNode> childNodes = null;
        boolean isParentData = false;
        if (StringUtils.startsWith(path, PbSourceData.ROOT_KEY)) {
            childNodes = pbData.parseStructNodeList(path, pbData.getRootDesc());
        } else if (StringUtils.startsWith(path, PbSourceData.CHILD_KEY)) {
            if (pbData.getChildDesc() == null) {
                return null;
            }
            childNodes = pbData.parseStructNodeList(path, pbData.getChildDesc());
        } else if (parentDesc != null) {
            childNodes = pbData.parseStructNodeList(path, parentDesc);
            isParentData = true;
        }
        if (childNodes == null || childNodes.size() <= 0) {
            return null;
        }
        // value
        Object currentNode = null;
        if (isParentData) {
            currentNode = pbData.findNodeValueByCache(childNodes, parentRoot);
        } else {
            currentNode = pbData.findFieldNode(rowIndex, path);
        }
        if (currentNode == null) {
            return null;
        }
        // array
        PbNode lastNode = childNodes.get(childNodes.size() - 1);
        // primitive
        if (lastNode.isPrimitiveType()) {
            return toByteArray(currentNode);
        }
        // struct
        if (lastNode.isStructType()) {
            return toByteArray(currentNode);
        }
        // array
        if (lastNode.isArrayType()) {
            if (!lastNode.isHasArrayIndex()) {
                if (!(currentNode instanceof List)) {
                    return null;
                }
                List<?> valueList = (List<?>) currentNode;
                List<Object> fieldResult = new ArrayList<>(valueList.size());
                for (Object value : valueList) {
                    fieldResult.add(toByteArray(value));
                }
                return new GenericArrayData(fieldResult.toArray());
            }
            return toByteArray(currentNode);
        }
        // map
        if (lastNode.isMapType()) {
            return toByteArray(currentNode);
        }
        return null;
    }

